class Speaker:
    def __init__(self, enabled=True, speech_rate=165):
        self.enabled = enabled
        self.stop_event = threading.Event()
        self.q = queue.Queue(maxsize=1)
        self.thread = None
        if enabled:
            self.thread = threading.Thread(target=self._worker, args=(speech_rate,), daemon=True)
            self.thread.start()

    def _worker(self, rate):
        engine = None
        try:
            import pyttsx3
            engine = pyttsx3.init()
            engine.setProperty("rate", rate)
            while not self.stop_event.is_set():
                try:
                    msg = self.q.get(timeout=0.2)
                except queue.Empty:
                    continue
                if not self.stop_event.is_set():
                    engine.say(msg)
                    engine.runAndWait()
        except Exception as exc:
            print(f"[Audio Engine Unavailable]: {exc}")
        finally:
            if engine is not None:
                engine.stop()

    def say(self, msg):
        print(f"[Audio Announcement]: \"{msg}\"")
        if self.enabled:
            try:
                self.q.put_nowait(msg)
            except queue.Full:
                pass

    def close(self):
        self.stop_event.set()
        if self.thread:
            self.thread.join(timeout=2)

